def add_menu_entry(apps, schema_editor):
    """Existing installs: add "Background jobs" to the Administration group (fresh databases get it from menu/defaults.py). Skipped
    when the group is gone or the page is already in the menu, so an administrator's menu is never changed otherwise."""
    MenuItem = apps.get_model("core", "MenuItem")
    db = schema_editor.connection.alias
    group = MenuItem.objects.using(db).filter(title="Administration", parent=None, url_name="").first()
    if group is None or MenuItem.objects.using(db).filter(url_name="core:job_list").exists():
        return
    after = MenuItem.objects.using(db).filter(parent=group, url_name="core:export_jobs").first()
    MenuItem.objects.using(db).create(title="Background jobs", icon="player-play", url_name="core:job_list", path="",
                                      permission="core.view_jobrecord", superuser_only=False, parent=group,
                                      position=(after.position + 5) if after else 1000)


